//! The text of HELP: the basic help and a one-line description of every built-in word
//! and of the words the parser handles. The descriptions are written for FORTH/Sigma.

pub const Entry = struct { name: []const u8, stack: []const u8, text: []const u8 };

pub const basic =
    \\FORTH/Sigma follows gforth in most words. The user manual is USER_MANUAL.md
    \\(docs\ in the installed folder, docs/ in the source).
    \\  WORDS         list the words of the first word list in the search order
    \\  HELP name     describe a word, for example HELP DUP
    \\  SEE name      show how a word is defined
    \\  LOCATE name   show the file and lines where a word was defined
    \\  LICENSE       show the license
    \\  BYE           leave FORTH/Sigma
    \\Numbers: 123 is a cell, 123. a double cell, 1e or 1.5E3 a float (the E is needed);
    \\$FF is hexadecimal, %101 binary, #10 decimal, and 'a' a character code.
    \\Define a word with  : SQUARE DUP * ;  and run it with  5 SQUARE .
    \\
;

