    .{ .name = ">IN", .stack = "( -- addr )", .text = "The cell holding the offset of the next character in SOURCE; storing to it moves the input." },
    .{ .name = "SOURCE-ID", .stack = "( -- n )", .text = "0 for the terminal, -1 for EVALUATE, and the file id while a file is included." },
    .{ .name = "REFILL", .stack = "( -- flag )", .text = "Read the next line of the terminal or the file as the input; false at the end and in EVALUATE." },
    .{ .name = "SAVE-INPUT", .stack = "( -- x1 x2 x3 x4 4 )", .text = "Save the place in the input: the source, >IN, and the line." },
    .{ .name = "RESTORE-INPUT", .stack = "( x1 x2 x3 x4 4 -- flag )", .text = "Go back to a saved place; false if it worked. A file reads the line again; the terminal and EVALUATE stay in the same line." },

    // Defining words and the compiler
    .{ .name = ":", .stack = "( \"name\" -- )", .text = "Start the definition of name; ; ends it." },
    .{ .name = ";", .stack = "( -- )", .text = "End a colon definition." },
    .{ .name = "VARIABLE", .stack = "( \"name\" -- )", .text = "Make a variable of one cell; name pushes its address." },
    .{ .name = "VAR", .stack = "( \"name\" -- )", .text = "The FORTH/Sigma name of VARIABLE." },
    .{ .name = "CONSTANT", .stack = "( x \"name\" -- )", .text = "Make a constant; name pushes x." },
    .{ .name = "CONST", .stack = "( x \"name\" -- )", .text = "The FORTH/Sigma name of CONSTANT." },
    .{ .name = "VALUE", .stack = "( x \"name\" -- )", .text = "Make a value; name pushes it and TO name changes it." },
    .{ .name = "DEFER", .stack = "( \"name\" -- )", .text = "Make a deferred word; IS name sets the word that name runs." },
    .{ .name = "DEFER!", .stack = "( xt2 xt1 -- )", .text = "Make the DEFER xt1 run xt2." },
    .{ .name = "DEFER@", .stack = "( xt1 -- xt2 )", .text = "The word the DEFER xt1 runs." },
    .{ .name = "DEFERS", .stack = "( \"name\" -- )", .text = "Compile the word that the DEFER name runs now." },
    .{ .name = "IS", .stack = "( xt \"name\" -- )", .text = "Make the DEFER name run xt; the same as TO." },
    .{ .name = "ACTION-OF", .stack = "( \"name\" -- xt )", .text = "The word the DEFER name runs." },
    .{ .name = "+TO", .stack = "( n \"name\" -- )", .text = "Add n to a VALUE (r to an FVALUE, d to a 2VALUE)." },
    .{ .name = "ARRAY", .stack = "( n \"name\" -- )", .text = "Make an array of n cells; name pushes its address, used with A@ and A!." },
    .{ .name = "FARRAY", .stack = "( n \"name\" -- )", .text = "Make an array of n floats; name pushes its address, used with FA@ and FA!." },
    .{ .name = "CREATE", .stack = "( \"name\" -- )", .text = "Make a word that pushes the address of the data space after it; add DOES> for a behaviour." },
    .{ .name = "<BUILDS", .stack = "( \"name\" -- )", .text = "The FORTH/Sigma name of CREATE." },
    .{ .name = "DOES>", .stack = "( -- addr )", .text = "In a defining word, give the words it creates this behaviour; they start with their data address." },
    .{ .name = "IMMEDIATE", .stack = "( -- )", .text = "Make the last word run even while compiling." },
    .{ .name = "EXECUTE", .stack = "( xt -- )", .text = "Run the word with the execution token xt." },
    .{ .name = "PERFORM", .stack = "( addr -- )", .text = "Run the execution token stored at addr: @ EXECUTE." },
    .{ .name = "NOOP", .stack = "( -- )", .text = "Do nothing." },
    .{ .name = "COMPILE,", .stack = "( xt -- )", .text = "Append the execution of xt to the definition being compiled." },
    .{ .name = "[COMPILE]", .stack = "( \"name\" -- )", .text = "Append the execution of name, also for an immediate word." },
    .{ .name = "'", .stack = "( \"name\" -- xt )", .text = "The execution token of name; in a definition, name is read when the definition runs." },
    .{ .name = ">BODY", .stack = "( xt -- addr )", .text = "The data address of a word made by CREATE, VARIABLE, VALUE, 2CONSTANT, or ARRAY." },
    .{ .name = "LITERAL", .stack = "( x -- )", .text = "While compiling, compile x so that it is pushed when the definition runs." },
    .{ .name = "FLITERAL", .stack = "( F: r -- )", .text = "While compiling, compile the float r." },
    .{ .name = "SLITERAL", .stack = "( addr u -- )", .text = "While compiling, compile the string (at most 255 bytes); the definition then gives addr u." },
    .{ .name = "2LITERAL", .stack = "( d -- )", .text = "While compiling, compile the double-cell number d." },
    .{ .name = "STATE", .stack = "( -- addr )", .text = "The address of a cell that is -1 while compiling and 0 while interpreting." },
    .{ .name = "RECURSE", .stack = "( -- )", .text = "Call the definition being compiled." },
    .{ .name = "EXIT", .stack = "( -- )", .text = "Return from the current definition." },
    .{ .name = "?EXIT", .stack = "( flag -- )", .text = "Return from the current definition if flag is true." },
    .{ .name = "?LEAVE", .stack = "( flag -- )", .text = "Leave the innermost DO loop if flag is true." },

    // Control structures
    .{ .name = "IF", .stack = "( flag -- )", .text = "flag IF ... ELSE ... THEN runs the first part if flag is true, otherwise the second." },
    .{ .name = "ELSE", .stack = "( -- )", .text = "Start the part of IF that runs when the flag is false." },
    .{ .name = "AHEAD", .stack = "( -- )", .text = "In a definition, branch forward always; THEN marks where to." },
    .{ .name = "THEN", .stack = "( -- )", .text = "End an IF." },
    .{ .name = "ENDIF", .stack = "( -- )", .text = "The same as THEN." },
    .{ .name = "BEGIN", .stack = "( -- )", .text = "Start a loop: BEGIN ... UNTIL, BEGIN ... AGAIN, or BEGIN ... WHILE ... REPEAT." },
    .{ .name = "UNTIL", .stack = "( flag -- )", .text = "Go back to BEGIN while flag is false." },
    .{ .name = "END", .stack = "( flag -- )", .text = "The FORTH/Sigma name of UNTIL." },
    .{ .name = "AGAIN", .stack = "( -- )", .text = "Go back to BEGIN forever (leave with EXIT)." },
    .{ .name = "WHILE", .stack = "( flag -- )", .text = "Leave a BEGIN ... WHILE ... REPEAT loop when flag is false." },
    .{ .name = "REPEAT", .stack = "( -- )", .text = "Go back to BEGIN." },
    .{ .name = "CS-PICK", .stack = "( u -- )", .text = "While compiling, copy the u-th entry of the control-flow stack to its top." },
    .{ .name = "CS-ROLL", .stack = "( u -- )", .text = "While compiling, move the u-th entry of the control-flow stack to its top." },
    .{ .name = "DO", .stack = "( limit start -- )", .text = "Start a counted loop; the body runs at least once, and exactly once when limit equals start (FORTH/Sigma)." },
    .{ .name = "?DO", .stack = "( limit start -- )", .text = "Start a counted loop that is skipped when limit equals start." },
    .{ .name = "LOOP", .stack = "( -- )", .text = "Add one to the index and repeat until it reaches the limit; a loop whose limit equals its start ends after one pass." },
    .{ .name = "+LOOP", .stack = "( n -- )", .text = "Add n to the index and repeat until it crosses the limit; a loop whose limit equals its start ends after one pass, even when n is 0." },
    .{ .name = "I", .stack = "( -- n )", .text = "The index of the innermost loop." },
    .{ .name = "J", .stack = "( -- n )", .text = "The index of the next outer loop." },
    .{ .name = "K", .stack = "( -- n )", .text = "The index of the third loop out." },
    .{ .name = "LEAVE", .stack = "( -- )", .text = "Leave the innermost loop at once." },
    .{ .name = "UNLOOP", .stack = "( -- )", .text = "Drop the innermost loop's parameters, before EXIT inside a loop." },
    .{ .name = "CASE", .stack = "( x -- x )", .text = "Start CASE n OF ... ENDOF ... ENDCASE, which runs the branch whose value equals x." },
    .{ .name = "OF", .stack = "( x n -- | x )", .text = "Run up to ENDOF if x equals n (dropping both), otherwise skip it." },
    .{ .name = "ENDOF", .stack = "( -- )", .text = "End a branch of CASE." },
    .{ .name = "ENDCASE", .stack = "( x -- )", .text = "End a CASE and drop the selector." },
    .{ .name = "?OF", .stack = "( flag -- )", .text = "Like OF, but run the branch if flag is true." },
    .{ .name = "CONTOF", .stack = "( -- )", .text = "End an OF branch and go back to CASE." },
    .{ .name = "NEXT-CASE", .stack = "( x -- x )", .text = "End a CASE and go back to its start, keeping the selector." },
    .{ .name = "[IF]", .stack = "( flag -- )", .text = "If flag is false, skip the input up to [ELSE] or [THEN], across lines." },
    .{ .name = "[ELSE]", .stack = "( -- )", .text = "Skip the input up to the matching [THEN]." },
    .{ .name = "[THEN]", .stack = "( -- )", .text = "End [IF]." },
    .{ .name = "[DEFINED]", .stack = "( \"name\" -- flag )", .text = "True if name is found in the search order." },
    .{ .name = "[UNDEFINED]", .stack = "( \"name\" -- flag )", .text = "True if name is not found in the search order." },
    .{ .name = "[IFDEF]", .stack = "( \"name\" -- )", .text = "Like [DEFINED] name [IF]." },
    .{ .name = "[IFUNDEF]", .stack = "( \"name\" -- )", .text = "Like [UNDEFINED] name [IF]." },
    .{ .name = "[ENDIF]", .stack = "( -- )", .text = "Same as [THEN]." },
    .{ .name = "[DO]", .stack = "( limit start -- )", .text = "Repeat the input up to [LOOP] or [+LOOP] while interpreting." },
    .{ .name = "[?DO]", .stack = "( limit start -- )", .text = "Like [DO], but skip the loop if limit equals start." },
    .{ .name = "[LOOP]", .stack = "( -- )", .text = "Add 1 to the [DO] index and repeat until it reaches the limit." },
    .{ .name = "[+LOOP]", .stack = "( n -- )", .text = "Add n to the [DO] index and repeat until it crosses the limit." },
    .{ .name = "[I]", .stack = "( -- n )", .text = "The index of the innermost [DO] or [FOR] loop." },
    .{ .name = "[BEGIN]", .stack = "( -- )", .text = "Start a loop that repeats the input while interpreting." },
    .{ .name = "[UNTIL]", .stack = "( flag -- )", .text = "Repeat from [BEGIN] until flag is true." },
    .{ .name = "[AGAIN]", .stack = "( -- )", .text = "Repeat from [BEGIN] forever." },
    .{ .name = "[WHILE]", .stack = "( flag -- )", .text = "If flag is false, leave the [BEGIN] loop after [REPEAT]." },
    .{ .name = "[REPEAT]", .stack = "( -- )", .text = "Repeat from [BEGIN]." },
    .{ .name = "[FOR]", .stack = "( n -- )", .text = "Repeat the input up to [NEXT] with the index going from n down to 0." },
    .{ .name = "[NEXT]", .stack = "( -- )", .text = "Subtract 1 from the [FOR] index and repeat until it passes 0." },

    // Floating point
    .{ .name = "FDROP", .stack = "( F: r -- )", .text = "Remove the top float." },
    .{ .name = "FDUP", .stack = "( F: r -- r r )", .text = "Copy the top float." },
    .{ .name = "FSWAP", .stack = "( F: r1 r2 -- r2 r1 )", .text = "Exchange the top two floats." },
    .{ .name = "FOVER", .stack = "( F: r1 r2 -- r1 r2 r1 )", .text = "Copy the second float to the top." },
    .{ .name = "FROT", .stack = "( F: r1 r2 r3 -- r2 r3 r1 )", .text = "Move the third float to the top." },
    .{ .name = "F-ROT", .stack = "( F: r1 r2 r3 -- r3 r1 r2 )", .text = "Move the top float below the next two." },
    .{ .name = "FNIP", .stack = "( F: r1 r2 -- r2 )", .text = "Remove the second float." },
    .{ .name = "FTUCK", .stack = "( F: r1 r2 -- r2 r1 r2 )", .text = "Copy the top float below the second." },
    .{ .name = "FPICK", .stack = "( u -- ) ( F: -- r )", .text = "Copy the u-th float below the top." },
    .{ .name = "FDEPTH", .stack = "( -- u )", .text = "The number of floats on the float stack." },
    .{ .name = "F.S", .stack = "( -- )", .text = "Show the float depth and the top nine floats as 14 0 17 F.RDP shows them." },
    .{ .name = "F+", .stack = "( F: r1 r2 -- r3 )", .text = "Add floats." },
    .{ .name = "F-", .stack = "( F: r1 r2 -- r3 )", .text = "Subtract r2 from r1." },
    .{ .name = "F*", .stack = "( F: r1 r2 -- r3 )", .text = "Multiply floats." },
    .{ .name = "F/", .stack = "( F: r1 r2 -- r3 )", .text = "Divide r1 by r2; dividing by zero gives infinity or NaN." },
    .{ .name = "FNEGATE", .stack = "( F: r -- -r )", .text = "Negate a float." },
    .{ .name = "FMINUS", .stack = "( F: r -- -r )", .text = "The same as FNEGATE." },
    .{ .name = "FABS", .stack = "( F: r -- r' )", .text = "The absolute value of a float." },
    .{ .name = "FMAX", .stack = "( F: r1 r2 -- r3 )", .text = "The greater float." },
    .{ .name = "FMIN", .stack = "( F: r1 r2 -- r3 )", .text = "The smaller float." },
    .{ .name = "FSQRT", .stack = "( F: r -- r' )", .text = "The square root." },
    .{ .name = "FEXP", .stack = "( F: r -- r' )", .text = "e to the power r, correctly rounded." },
    .{ .name = "FLN", .stack = "( F: r -- r' )", .text = "The natural logarithm, correctly rounded." },
    .{ .name = "FSIN", .stack = "( F: r -- r' )", .text = "The sine of r radians, correctly rounded." },
    .{ .name = "FCOS", .stack = "( F: r -- r' )", .text = "The cosine of r radians, correctly rounded." },
    .{ .name = "FTAN", .stack = "( F: r -- r' )", .text = "The tangent of r radians, correctly rounded." },
    .{ .name = "FSINCOS", .stack = "( F: r -- r-sin r-cos )", .text = "The sine and cosine of r radians, correctly rounded; the cosine on top." },
    .{ .name = "FASIN", .stack = "( F: r -- r' )", .text = "The arcsine in radians, correctly rounded." },
    .{ .name = "FACOS", .stack = "( F: r -- r' )", .text = "The arccosine in radians, correctly rounded." },
    .{ .name = "FATAN", .stack = "( F: r -- r' )", .text = "The arctangent in radians, correctly rounded." },
    .{ .name = "FATAN2", .stack = "( F: y x -- r )", .text = "The angle of the point (x, y) in radians, from -pi to pi, correctly rounded." },
    .{ .name = "FSINH", .stack = "( F: r -- r' )", .text = "The hyperbolic sine, correctly rounded." },
    .{ .name = "FCOSH", .stack = "( F: r -- r' )", .text = "The hyperbolic cosine, correctly rounded." },
    .{ .name = "FTANH", .stack = "( F: r -- r' )", .text = "The hyperbolic tangent, correctly rounded." },
    .{ .name = "FASINH", .stack = "( F: r -- r' )", .text = "The inverse hyperbolic sine, correctly rounded." },
    .{ .name = "FACOSH", .stack = "( F: r -- r' )", .text = "The inverse hyperbolic cosine, correctly rounded." },
    .{ .name = "FATANH", .stack = "( F: r -- r' )", .text = "The inverse hyperbolic tangent, correctly rounded." },
    .{ .name = "FEXPM1", .stack = "( F: r -- r' )", .text = "e to the power r, minus 1, correctly rounded (exact also for tiny r)." },
    .{ .name = "FLNP1", .stack = "( F: r -- r' )", .text = "The natural logarithm of 1 + r, correctly rounded (exact also for tiny r)." },
    .{ .name = "FLOG", .stack = "( F: r -- r' )", .text = "The base-10 logarithm, correctly rounded." },
    .{ .name = "FALOG", .stack = "( F: r -- r' )", .text = "10 to the power r, correctly rounded." },
    .{ .name = "F**", .stack = "( F: r1 r2 -- r3 )", .text = "r1 to the power r2, correctly rounded." },
    .{ .name = "FLOOR", .stack = "( F: r -- r' )", .text = "Round down to an integer." },
    .{ .name = "FTRUNC", .stack = "( F: r -- r' )", .text = "Round toward zero to an integer." },
    .{ .name = "FROUND", .stack = "( F: r -- r' )", .text = "Round to the nearest integer; halves go to the even one." },
    .{ .name = "PI", .stack = "( F: -- r )", .text = "The float closest to pi." },
    .{ .name = "F=", .stack = "( F: r1 r2 -- ) ( -- flag )", .text = "True if the floats are equal; the flag goes on the data stack." },
    .{ .name = "F<>", .stack = "( F: r1 r2 -- ) ( -- flag )", .text = "True if the floats are not equal." },
    .{ .name = "F<", .stack = "( F: r1 r2 -- ) ( -- flag )", .text = "True if r1 is less than r2." },
    .{ .name = "F>", .stack = "( F: r1 r2 -- ) ( -- flag )", .text = "True if r1 is greater than r2." },
    .{ .name = "F~", .stack = "( F: r1 r2 r3 -- ) ( -- flag )", .text = "Approximate equality: r3 > 0 an absolute bound, r3 = 0 the same bits, r3 < 0 a bound relative to |r1| + |r2|." },
    .{ .name = "F<=", .stack = "( F: r1 r2 -- ) ( -- flag )", .text = "True if r1 is less than or equal to r2." },
    .{ .name = "F>=", .stack = "( F: r1 r2 -- ) ( -- flag )", .text = "True if r1 is greater than or equal to r2." },
    .{ .name = "F0=", .stack = "( F: r -- ) ( -- flag )", .text = "True if the float is zero." },
    .{ .name = "F0<>", .stack = "( F: r -- ) ( -- flag )", .text = "True if the float is not zero." },
    .{ .name = "F0<", .stack = "( F: r -- ) ( -- flag )", .text = "True if the float is negative." },
    .{ .name = "F0>", .stack = "( F: r -- ) ( -- flag )", .text = "True if the float is positive." },
    .{ .name = "F0<=", .stack = "( F: r -- ) ( -- flag )", .text = "True if the float is zero or negative." },
    .{ .name = "F0>=", .stack = "( F: r -- ) ( -- flag )", .text = "True if the float is zero or positive." },
    .{ .name = "F@", .stack = "( addr -- ) ( F: -- r )", .text = "Fetch a float (8 bytes)." },
    .{ .name = "F!", .stack = "( addr -- ) ( F: r -- )", .text = "Store a float." },
    .{ .name = "SF@", .stack = "( addr -- ) ( F: -- r )", .text = "Fetch a 32-bit float." },
    .{ .name = "SF!", .stack = "( addr -- ) ( F: r -- )", .text = "Store r as a 32-bit float." },
    .{ .name = "DF@", .stack = "( addr -- ) ( F: -- r )", .text = "Fetch a 64-bit float, as F@." },
    .{ .name = "DF!", .stack = "( addr -- ) ( F: r -- )", .text = "Store a 64-bit float, as F!." },
    .{ .name = "F,", .stack = "( F: r -- )", .text = "Store a float at HERE and advance HERE." },
    .{ .name = "FA@", .stack = "( i addr -- ) ( F: -- r )", .text = "Fetch element i of the float array at addr (see FARRAY)." },
    .{ .name = "FA!", .stack = "( i addr -- ) ( F: r -- )", .text = "Store r as element i of the float array at addr." },
    .{ .name = "F+!", .stack = "( addr -- ) ( F: r -- )", .text = "Add r to the float at addr." },
    .{ .name = "F?", .stack = "( addr -- )", .text = "Print the float at addr as F. does." },
    .{ .name = "FLOATS", .stack = "( n -- n*8 )", .text = "The size of n floats in bytes." },
    .{ .name = "FLOAT+", .stack = "( addr -- addr+8 )", .text = "Add the size of a float." },
    .{ .name = "SFLOATS", .stack = "( n -- n' )", .text = "The bytes of n 32-bit floats." },
    .{ .name = "DFLOATS", .stack = "( n -- n' )", .text = "The bytes of n 64-bit floats." },
    .{ .name = "SFLOAT+", .stack = "( addr -- addr+4 )", .text = "Add the size of a 32-bit float." },
    .{ .name = "DFLOAT+", .stack = "( addr -- addr+8 )", .text = "Add the size of a 64-bit float." },
    .{ .name = "FALIGN", .stack = "( -- )", .text = "Round HERE up to a multiple of 8, the size of a float." },
    .{ .name = "FALIGNED", .stack = "( addr -- addr' )", .text = "Round up to a multiple of 8." },
    .{ .name = "SFALIGN", .stack = "( -- )", .text = "Round HERE up to a multiple of 4." },
    .{ .name = "SFALIGNED", .stack = "( addr -- addr' )", .text = "Round up to a multiple of 4." },
    .{ .name = "DFALIGN", .stack = "( -- )", .text = "Round HERE up to a multiple of 8." },
    .{ .name = "DFALIGNED", .stack = "( addr -- addr' )", .text = "Round up to a multiple of 8." },
    .{ .name = "S>F", .stack = "( n -- ) ( F: -- r )", .text = "Convert a cell to a float." },
    .{ .name = "F>S", .stack = "( F: r -- ) ( -- n )", .text = "Convert a float to a cell, truncating toward zero." },
    .{ .name = "D>F", .stack = "( d -- ) ( F: -- r )", .text = "Convert a double cell to a float." },
    .{ .name = "F>D", .stack = "( F: r -- ) ( -- d )", .text = "Convert a float to a double cell, truncating toward zero." },
    .{ .name = "F.", .stack = "( F: r -- )", .text = "Print a float with PRECISION (15) significant digits, without an exponent, and a space." },
    .{ .name = "FE.", .stack = "( F: r -- )", .text = "Print r with PRECISION digits and an exponent that is a multiple of 3, and a space." },
    .{ .name = "FS.", .stack = "( F: r -- )", .text = "Print r with PRECISION digits, one before the point, an exponent, and a space." },
    .{ .name = "REPRESENT", .stack = "( addr u -- n flag1 flag2 ) ( F: r -- )", .text = "Store u digits of r at addr; n is the exponent of 0.digits, flag1 the sign, flag2 whether r is finite." },
    .{ .name = "PRECISION", .stack = "( -- u )", .text = "The significant digits F. FE. and FS. show (15 at startup)." },
    .{ .name = "SET-PRECISION", .stack = "( u -- )", .text = "Set PRECISION; output uses 1 to 1000 digits." },
    .{ .name = "F.RDP", .stack = "( nr nd np -- ) ( F: r -- )", .text = "Print r right-aligned in nr characters with nd digits after the point, or in exponent form when fewer than np digits would show." },
    .{ .name = "F>STR-RDP", .stack = "( nr nd np -- addr u ) ( F: r -- )", .text = "Format r as F.RDP does; the string lasts until the next number conversion." },
    .{ .name = "F>BUF-RDP", .stack = "( addr nr nd np -- ) ( F: r -- )", .text = "Format r as F.RDP does into the buffer at addr." },
    .{ .name = "FINPUT", .stack = "( F: -- r )", .text = "Read a float from the terminal (the E may be left out)." },
    .{ .name = ">FLOAT", .stack = "( addr u -- flag ) ( F: -- r | )", .text = "Convert a string to a float; the E may be left out. The float is pushed only on success." },
    .{ .name = "FVARIABLE", .stack = "( \"name\" -- )", .text = "Make a float variable; name pushes its address." },
    .{ .name = "FCONSTANT", .stack = "( \"name\" -- ) ( F: r -- )", .text = "Make a float constant; name pushes r." },
    .{ .name = "FVALUE", .stack = "( \"name\" -- ) ( F: r -- )", .text = "Make a float value; name pushes it and TO name stores a new one." },
    .{ .name = "2VALUE", .stack = "( \"name\" -- ) ( d -- )", .text = "Make a double-cell value; name pushes it and TO name stores a new one." },
    .{ .name = "BUFFER:", .stack = "( u \"name\" -- )", .text = "Reserve u bytes of data space; name pushes their address." },

    // Pictured numeric output and number conversion
    .{ .name = "<#", .stack = "( -- )", .text = "Start a number conversion, emptying every hold area." },
    .{ .name = "<<#", .stack = "( -- )", .text = "Start a nested number conversion (up to 16); end it with #>>." },
    .{ .name = "#", .stack = "( ud -- ud' )", .text = "Convert the lowest digit." },
    .{ .name = "#S", .stack = "( ud -- 0 0 )", .text = "Convert all remaining digits." },
    .{ .name = "#>", .stack = "( ud -- addr u )", .text = "End the conversion and return the string." },
    .{ .name = "#>>", .stack = "( -- )", .text = "Release the hold area started by <<#." },
    .{ .name = "HOLD", .stack = "( c -- )", .text = "Add a character to the front of the conversion." },
    .{ .name = "HOLDS", .stack = "( addr u -- )", .text = "Add a string to the front of the conversion." },
    .{ .name = "SIGN", .stack = "( n -- )", .text = "Add a minus sign if n is negative." },
    .{ .name = ">NUMBER", .stack = "( ud addr u -- ud' addr' u' )", .text = "Convert digits, returning the part that could not be converted." },
    .{ .name = "S>NUMBER?", .stack = "( addr u -- d flag )", .text = "Convert a string to a double cell; flag tells whether it worked." },

    // Dictionary and word lists
    .{ .name = "WORDS", .stack = "( -- )", .text = "List the words of the first word list in the search order." },
    .{ .name = "FIND", .stack = "( c-addr -- c-addr 0 | xt 1 | xt -1 )", .text = "Find a counted-string name; 1 for an immediate word, -1 for others." },
    .{ .name = "FIND-NAME", .stack = "( addr u -- nt | 0 )", .text = "Find a name and return its name token, or 0." },
    .{ .name = "NAME>INT", .stack = "( nt -- xt )", .text = "The execution token of a name token." },
    .{ .name = "NAME>INTERPRET", .stack = "( nt -- xt )", .text = "The execution token of a name token, as NAME>INT." },
    .{ .name = "NAME>COMPILE", .stack = "( nt -- xt1 xt2 )", .text = "xt2 is COMPILE, or EXECUTE (for an immediate word); run it on xt1 to compile name." },
    .{ .name = "NAME>STRING", .stack = "( nt -- addr u )", .text = "The name of a name token; the string lasts for eight calls." },
    .{ .name = "SEE", .stack = "( \"name\" -- )", .text = "Show how name is defined, rebuilt from its compiled code." },
    .{ .name = "LOCATE", .stack = "( \"name\" -- )", .text = "Show the file, the line, and the lines of the definition of name." },
    .{ .name = "WHERE", .stack = "( \"name\" -- )", .text = "List the places in the included files where name was used." },
    .{ .name = "MARKER", .stack = "( \"name\" -- )", .text = "Make name; running it forgets name, every later word, and the files required since." },
    .{ .name = "FORGET", .stack = "( \"name\" -- )", .text = "Remove name and every later word, reclaiming their space." },
    .{ .name = "VOCABULARY", .stack = "( \"name\" -- )", .text = "Make a word list; name puts it first in the search order." },
    .{ .name = "WORDLIST", .stack = "( -- wid )", .text = "Make an unnamed word list." },
    .{ .name = "FORTH", .stack = "( -- )", .text = "Put the Forth word list first in the search order." },
    .{ .name = "FORTH-WORDLIST", .stack = "( -- wid )", .text = "The Forth word list." },
    .{ .name = "ONLY", .stack = "( -- )", .text = "Reduce the search order to Root Root; FORTH usually follows." },
    .{ .name = "ALSO", .stack = "( -- )", .text = "Duplicate the first word list of the search order." },
    .{ .name = "PREVIOUS", .stack = "( -- )", .text = "Remove the first word list of the search order." },
    .{ .name = "DEFINITIONS", .stack = "( -- )", .text = "Make new words go into the first word list of the search order." },
    .{ .name = "ORDER", .stack = "( -- )", .text = "Show the search order and, after a space, the list new words go into." },
    .{ .name = "GET-ORDER", .stack = "( -- wid ... n )", .text = "The search order, first list on top." },
    .{ .name = "SET-ORDER", .stack = "( wid ... n -- )", .text = "Set the search order; -1 SET-ORDER is ONLY." },
    .{ .name = ">ORDER", .stack = "( wid -- )", .text = "Put a word list first in the search order." },
    .{ .name = "GET-CURRENT", .stack = "( -- wid )", .text = "The word list new words go into." },
    .{ .name = "SET-CURRENT", .stack = "( wid -- )", .text = "Make new words go into wid." },
    .{ .name = "SEARCH-WORDLIST", .stack = "( addr u wid -- 0 | xt 1 | xt -1 )", .text = "Find a name in one word list." },
    .{ .name = "TRAVERSE-WORDLIST", .stack = "( xt wid -- )", .text = "Run xt ( nt -- flag ) for each word of the list, newest first, until it gives false." },
    .{ .name = "SYNONYM", .stack = "( \"new\" \"old\" -- )", .text = "Make new a name for the word old, immediate if old is." },

    // Files and source files
    .{ .name = "R/O", .stack = "( -- fam )", .text = "Read-only access." },
    .{ .name = "W/O", .stack = "( -- fam )", .text = "Write-only access." },
    .{ .name = "R/W", .stack = "( -- fam )", .text = "Read and write access." },
    .{ .name = "STDIN", .stack = "( -- fileid )", .text = "Standard input." },
    .{ .name = "STDOUT", .stack = "( -- fileid )", .text = "Standard output." },
    .{ .name = "STDERR", .stack = "( -- fileid )", .text = "Standard error." },
    .{ .name = "OPEN-FILE", .stack = "( addr u fam -- fileid ior )", .text = "Open an existing file." },
    .{ .name = "CREATE-FILE", .stack = "( addr u fam -- fileid ior )", .text = "Create a file, emptying it if it exists." },
    .{ .name = "CLOSE-FILE", .stack = "( fileid -- ior )", .text = "Close a file." },
    .{ .name = "READ-LINE", .stack = "( addr u fileid -- u2 flag ior )", .text = "Read a line of at most u characters without its end; flag is false at the end of the file." },
    .{ .name = "READ-FILE", .stack = "( addr u fileid -- u2 ior )", .text = "Read up to u bytes as they are; u2 is 0 at the end of the file." },
    .{ .name = "WRITE-LINE", .stack = "( addr u fileid -- ior )", .text = "Write a string and a line end." },
    .{ .name = "WRITE-FILE", .stack = "( addr u fileid -- ior )", .text = "Write a string." },
    .{ .name = "FILE-SIZE", .stack = "( fileid -- ud ior )", .text = "The size of the file in bytes." },
    .{ .name = "REPOSITION-FILE", .stack = "( ud fileid -- ior )", .text = "Move the read and write position." },
    .{ .name = "FILE-POSITION", .stack = "( fileid -- ud ior )", .text = "The read and write position." },
    .{ .name = "RESIZE-FILE", .stack = "( ud fileid -- ior )", .text = "Cut the file to ud bytes or extend it with zero bytes; the position stays." },
    .{ .name = "FLUSH-FILE", .stack = "( fileid -- ior )", .text = "Write what is buffered to the file." },
    .{ .name = "DELETE-FILE", .stack = "( addr u -- ior )", .text = "Delete the named file." },
    .{ .name = "RENAME-FILE", .stack = "( addr1 u1 addr2 u2 -- ior )", .text = "Rename the file named by the first string to the second, replacing a file of that name." },
    .{ .name = "FILE-STATUS", .stack = "( addr u -- x ior )", .text = "ior is 0 if the named file exists; x is R/O, W/O, or R/W, as it can be opened." },
    .{ .name = "BIN", .stack = "( fam -- fam' )", .text = "Ask for a binary file; files are read and written as bytes anyway." },
    .{ .name = "SLURP-FILE", .stack = "( addr u -- addr' u' )", .text = "Read all of the named file into a new ALLOCATE block (free it with FREE)." },
    .{ .name = "INCLUDE", .stack = "( \"file\" -- )", .text = "Interpret a file line by line." },
    .{ .name = "INCLUDED", .stack = "( addr u -- )", .text = "Interpret the file named by the string." },
    .{ .name = "INCLUDE-FILE", .stack = "( fileid -- )", .text = "Interpret the open file, then close it." },
    .{ .name = "REQUIRE", .stack = "( \"file\" -- )", .text = "Interpret a file unless it has been loaded already." },
    .{ .name = "NEEDS", .stack = "( \"file\" -- )", .text = "The same as REQUIRE." },
    .{ .name = "REQUIRED", .stack = "( addr u -- )", .text = "REQUIRE with the file name as a string." },
    .{ .name = "INCLUDED?", .stack = "( addr u -- flag )", .text = "True if the file has been loaded." },
    .{ .name = "SOURCEFILENAME", .stack = "( -- addr u )", .text = "The name of the file being interpreted (*the terminal* at the terminal)." },
    .{ .name = "SOURCELINE#", .stack = "( -- u )", .text = "The line number in the file being interpreted (0 at the terminal)." },

    // Dynamic strings
    .{ .name = "$!", .stack = "( addr u $var -- )", .text = "Store a string in a string variable." },
    .{ .name = "$@", .stack = "( $var -- addr u )", .text = "The string of a string variable (0 0 when empty)." },
    .{ .name = "$@LEN", .stack = "( $var -- u )", .text = "The length of the string." },
    .{ .name = "$!LEN", .stack = "( u $var -- )", .text = "Change the length; added bytes are zero." },
    .{ .name = "$+!", .stack = "( addr u $var -- )", .text = "Append a string." },
    .{ .name = "C$+!", .stack = "( c $var -- )", .text = "Append a character." },
    .{ .name = "$.", .stack = "( $var -- )", .text = "Print the string." },
    .{ .name = "$DEL", .stack = "( $var off u -- )", .text = "Delete u characters from position off." },
    .{ .name = "$INS", .stack = "( addr u $var off -- )", .text = "Insert a string at position off." },
    .{ .name = "$OVER", .stack = "( addr u $var off -- )", .text = "Overwrite from position off." },
    .{ .name = "$FREE", .stack = "( $var -- )", .text = "Free the string and set the variable to 0." },
    .{ .name = "$INIT", .stack = "( $var -- )", .text = "Make the variable an empty string." },
    .{ .name = "$SPLIT", .stack = "( addr u c -- addr u1 addr2 u2 )", .text = "Split a string at the first c." },
    .{ .name = "$ITER", .stack = "( $var c xt -- )", .text = "Run xt ( addr u -- ) on each part of the string separated by c." },
    .{ .name = "$TMP", .stack = "( xt -- addr u )", .text = "Run xt and return what it printed as a string." },
    .{ .name = "$[]", .stack = "( n $[]var -- addr )", .text = "The address of element n of a string array, as a string variable." },
    .{ .name = "$[]!", .stack = "( addr u n $[]var -- )", .text = "Store a string as element n of a string array." },
    .{ .name = "$[]@", .stack = "( n $[]var -- addr u )", .text = "Element n of a string array." },
    .{ .name = "$[]#", .stack = "( $[]var -- n )", .text = "The number of elements." },
    .{ .name = "$[].", .stack = "( $[]var -- )", .text = "Print every element on its own line." },
    .{ .name = "$[]MAP", .stack = "( $[]var xt -- )", .text = "Run xt ( addr u -- ) on each element." },
    .{ .name = "$[]FREE", .stack = "( $[]var -- )", .text = "Free every element and the array." },
    .{ .name = "$[]SLURP", .stack = "( fileid $[]var -- )", .text = "Read a file line by line into a string array." },
    .{ .name = "$[]SLURP-FILE", .stack = "( addr u $[]var -- )", .text = "Read the named file line by line into a string array." },
    .{ .name = "$+SLURP-FILE", .stack = "( addr u $var -- )", .text = "Append all of the named file to a dynamic string." },
    .{ .name = "$SLURP", .stack = "( fid $var -- )", .text = "Read the file from its position to the end into a dynamic string, replacing its text." },
    .{ .name = "$+SLURP", .stack = "( fid $var -- )", .text = "Append the file from its position to the end to a dynamic string." },
    .{ .name = "$SLURP-LINE", .stack = "( fid $var -- flag )", .text = "Read the next line into a dynamic string; flag is false at the end of the file." },
    .{ .name = "$+!LEN", .stack = "( u $var -- addr )", .text = "Lengthen the string by u bytes and return the address of the added part." },
    .{ .name = "$[]+!", .stack = "( addr u n $[]var -- )", .text = "Append a string to element n of a string array." },
    .{ .name = "$+[]!", .stack = "( addr u $[]var -- )", .text = "Store a string as the new last element of a string array." },
    .{ .name = "$EXEC", .stack = "( xt $var -- )", .text = "Run xt and append what it prints to the dynamic string." },
    .{ .name = "$OFF", .stack = "( $var -- )", .text = "Same as $FREE (an old name in gforth)." },
    .{ .name = "$VARIABLE", .stack = "( \"name\" -- )", .text = "Make a variable for a dynamic string; the same as VARIABLE." },
    .{ .name = "$[]VARIABLE", .stack = "( \"name\" -- )", .text = "Make a variable for a string array; the same as VARIABLE." },
    .{ .name = "$SLURP-FILE", .stack = "( addr u $var -- )", .text = "Read all of the named file into a dynamic string, replacing its text." },

    // Exceptions and the system
    .{ .name = "THROW", .stack = "( n -- )", .text = "Do nothing for 0, ABORT for -1, otherwise raise exception n (caught by CATCH or reported)." },
    .{ .name = "CATCH", .stack = "( xt -- 0 | n )", .text = "Run xt; return 0, or the exception number with the stack depths restored." },
    .{ .name = "ABORT", .stack = "( -- )", .text = "Empty the stacks and return to the terminal without a message." },
    .{ .name = "MS", .stack = "( n -- )", .text = "Wait n milliseconds." },
    .{ .name = "UTIME", .stack = "( -- ud )", .text = "Microseconds since 1970-01-01, as a double cell." },
    .{ .name = "TIME&DATE", .stack = "( -- second minute hour day month year )", .text = "The local date and time." },
    .{ .name = "GETENV", .stack = "( addr u -- addr2 u2 )", .text = "The value of an environment variable (0 0 when unset)." },
    .{ .name = "ARGC", .stack = "( -- addr )", .text = "Variable holding the number of command-line arguments left, the program's name included." },
    .{ .name = "ARGV", .stack = "( -- addr )", .text = "Variable holding the address of the vector of argument addresses (NUL-terminated strings)." },
    .{ .name = "ARG", .stack = "( u -- addr count )", .text = "Command-line argument u (0 is the program's name); 0 0 when there is none." },
    .{ .name = "SHIFT-ARGS", .stack = "( -- )", .text = "Remove argument 1 from the command-line arguments." },
    .{ .name = "NEXT-ARG", .stack = "( -- addr count )", .text = "Argument 1, removed from the arguments (1 ARG SHIFT-ARGS); 0 0 when there is none." },
    .{ .name = "XC-SIZE", .stack = "( xc -- u )", .text = "The number of bytes of xc in UTF-8 (3 for a value above U+10FFFF, written as U+FFFD)." },
    .{ .name = "X-SIZE", .stack = "( addr u -- u2 )", .text = "The number of bytes of the first character of the string (1 for an empty string)." },
    .{ .name = "XC@+", .stack = "( addr -- addr2 xc )", .text = "Fetch the UTF-8 character at addr (U+FFFD if it is not one) and the address after it." },
    .{ .name = "XC@", .stack = "( addr -- xc )", .text = "Fetch the UTF-8 character at addr (U+FFFD if it is not one)." },
    .{ .name = "XC!+", .stack = "( xc addr -- addr2 )", .text = "Store xc in UTF-8 at addr and give the address after it." },
    .{ .name = "XC!+?", .stack = "( xc addr u -- addr2 u2 flag )", .text = "Store xc in UTF-8 if it fits in the u bytes at addr; flag tells whether it did." },
    .{ .name = "XC,", .stack = "( xc -- )", .text = "Append xc in UTF-8 to the data space." },
    .{ .name = "XCHAR+", .stack = "( addr -- addr2 )", .text = "The address of the character after the UTF-8 character at addr." },
    .{ .name = "XCHAR-", .stack = "( addr -- addr2 )", .text = "The address of the UTF-8 character before addr." },
    .{ .name = "XEMIT", .stack = "( xc -- )", .text = "Display the character xc (written in UTF-8)." },
    .{ .name = "XKEY", .stack = "( -- xc )", .text = "Read one character (its UTF-8 bytes) from the terminal." },
    .{ .name = "XKEY?", .stack = "( -- flag )", .text = "True when a character can be read without waiting." },
    .{ .name = "X-WIDTH", .stack = "( addr u -- n )", .text = "The number of columns the UTF-8 string takes on a terminal." },
    .{ .name = "XC-WIDTH", .stack = "( xc -- n )", .text = "The columns xc takes on a terminal: 0, 1, or 2, or -1 for one that is not shown." },
    .{ .name = "+X/STRING", .stack = "( addr u -- addr2 u2 )", .text = "Remove the first character from the string." },
    .{ .name = "X\\STRING-", .stack = "( addr u -- addr u2 )", .text = "Remove the last character from the string." },
    .{ .name = "-TRAILING-GARBAGE", .stack = "( addr u -- addr u2 )", .text = "Remove an incomplete UTF-8 character from the end of the string." },
    .{ .name = "XHOLD", .stack = "( xc -- )", .text = "Add xc in UTF-8 to the start of the pictured numeric output." },
    .{ .name = "EKEY>XCHAR", .stack = "( u -- u false | xc true )", .text = "Whether the keyboard event is a whole character." },
    .{ .name = "X@+/STRING", .stack = "( addr u -- addr2 u2 xc )", .text = "Take the first character of the string." },
    .{ .name = "SYSTEM", .stack = "( addr u -- )", .text = "Run a shell command (cmd.exe on Windows)." },
    .{ .name = "$?", .stack = "( -- n )", .text = "The status of the last SYSTEM: the wait status on Linux and macOS, the exit code on Windows." },
    .{ .name = "BYE", .stack = "( -- )", .text = "Leave FORTH/Sigma." },
    .{ .name = "QUIT", .stack = "( -- )", .text = "Leave what is running and wait for terminal input, keeping both data stacks; CATCH does not stop it." },
    .{ .name = "ENVIRONMENT?", .stack = "( addr u -- false | x true )", .text = "Ask for a system value such as MAX-N, /HOLD, or STACK-CELLS; false for any other name." },
    .{ .name = "SAVE", .stack = "( \"file\" -- )", .text = "Save the words you defined to an image file." },
    .{ .name = "LOAD", .stack = "( \"file\" -- )", .text = "Add the words of an image file made by SAVE to the dictionary." },
    .{ .name = "SAVESYS", .stack = "( \"file\" -- )", .text = "Write an executable that starts with the current dictionary." },
    .{ .name = "HELP", .stack = "( \"name\" -- )", .text = "Describe name, or show the basic help when no name follows on the line. In a definition, HELP reads the name when the definition runs." },
    .{ .name = "LICENSE", .stack = "( -- )", .text = "Show the license of FORTH/Sigma and of the code it includes." },

    // Words the parser handles
    .{ .name = "(", .stack = "( -- )", .text = "A comment up to )." },
    .{ .name = "\\", .stack = "( -- )", .text = "A comment to the end of the line." },
    .{ .name = ".(", .stack = "( -- )", .text = "Print the text up to ) at once." },
    .{ .name = "[", .stack = "( -- )", .text = "Stop compiling and interpret." },
    .{ .name = "]", .stack = "( -- )", .text = "Go back to compiling the current definition." },
    .{ .name = "[']", .stack = "( \"name\" -- )", .text = "Compile the execution token of name, which is read when compiling." },
    .{ .name = "CHAR", .stack = "( \"word\" -- xc )", .text = "The code point of the first character (UTF-8) of the next word." },
    .{ .name = "[CHAR]", .stack = "( \"word\" -- )", .text = "Compile the code point of the first character (UTF-8) of the next word." },
    .{ .name = "POSTPONE", .stack = "( \"name\" -- )", .text = "Compile name so that it is compiled, or run if immediate, when the definition runs." },
    .{ .name = "TO", .stack = "( x \"name\" -- )", .text = "Change a VALUE or a local variable." },
    .{ .name = ":NONAME", .stack = "( -- xt )", .text = "Start a definition without a name; ; leaves its execution token." },
    .{ .name = "{", .stack = "( \"names\" -- )", .text = "Declare local variables: { a b -- c } takes a and b from the stack." },
    .{ .name = "{:", .stack = "( \"names\" -- )", .text = "Declare local variables, the standard way: {: a b :}." },
    .{ .name = "LOCALS|", .stack = "( \"names\" -- )", .text = "Declare local variables; the first name takes the top of the stack." },
    .{ .name = "S\"", .stack = "( \"text\" -- addr u )", .text = "The string up to the next \"." },
    .{ .name = "C\"", .stack = "( \"text\" -- c-addr )", .text = "In a definition, the counted string up to the next \"." },
    .{ .name = "ABORT\"", .stack = "( flag \"text\" -- )", .text = "In a definition: if flag is not zero, show the text and abort (THROW -2)." },
    .{ .name = "S\\\"", .stack = "( \"text\" -- addr u )", .text = "The string up to the next \", with escapes such as \\n and \\t." },
    .{ .name = ".\"", .stack = "( \"text\" -- )", .text = "Print the text up to the next \"." },
    .{ .name = ".\\\"", .stack = "( \"text\" -- )", .text = "Print the text up to the next \", with escapes." },
    .{ .name = "\"", .stack = "( \"text\" -- addr u )", .text = "In a definition, the string up to the next \" (FORTH/Sigma)." },
    // Graphics (FORTH/Sigma): the GFX- words are in the GRAPHICS vocabulary.
    .{ .name = "REQUIRE-GRAPHICS", .stack = "( -- )", .text = "Load the graphics words into the GRAPHICS vocabulary, the first time only (FORTH/Sigma)." },
    .{ .name = "REQUIRE-GAME", .stack = "( -- )", .text = "Load the game words (sprites, tile maps) into the GAME vocabulary, after the graphics words, the first time only (FORTH/Sigma)." },
    .{ .name = "GFX-PIXEL", .stack = "( img x y -- rgb | -1 )", .text = "The color of pixel x y of any image (SCREEN too), -1 outside it (FORTH/Sigma)." },
    .{ .name = "GFX-TILEMAP", .stack = "( addr cols rows img tw th sx sy x y w h key -- )", .text = "Draw the w by h view at x y of a map of cols by rows tile bytes at addr, seen from its pixel sx sy, with tw by th tiles of img; key is the transparent color or negative (FORTH/Sigma)." },
    .{ .name = "GFX-INDEXED", .stack = "( addr w h palette x y key -- )", .text = "Draw at x y the w by h color numbers, one byte each at addr, with the colors of the 256 cells at palette; number key (0 to 255, else none) is left out (FORTH/Sigma)." },
    .{ .name = "GFX-ROW-SHIFT", .stack = "( table x y w h -- )", .text = "Move each row of the w by h rectangle at x y of the image drawn on to the right by its cell of table, inside the rectangle (FORTH/Sigma)." },
    .{ .name = "GFX-ROW-COLOR", .stack = "( table rgb x y w h -- )", .text = "Give the pixels of color rgb in each row of the w by h rectangle at x y the color in its cell of table (FORTH/Sigma)." },
    .{ .name = "/SPRITE", .stack = "( -- n )", .text = "The bytes of a sprite, for an array of them made with INIT-SPRITE (FORTH/Sigma game)." },
    .{ .name = "SPRITE-X", .stack = "( spr -- addr )", .text = "The field of a sprite's x on the image drawn on (FORTH/Sigma game)." },
    .{ .name = "SPRITE-Y", .stack = "( spr -- addr )", .text = "The field of a sprite's y (FORTH/Sigma game)." },
    .{ .name = "SPRITE-IMAGE", .stack = "( spr -- addr )", .text = "The field of the image a sprite shows a part of (FORTH/Sigma game)." },
    .{ .name = "SPRITE-SX", .stack = "( spr -- addr )", .text = "The field of the x of a sprite's first frame in its image (FORTH/Sigma game)." },
    .{ .name = "SPRITE-SY", .stack = "( spr -- addr )", .text = "The field of the y of a sprite's frames in its image (FORTH/Sigma game)." },
    .{ .name = "SPRITE-W", .stack = "( spr -- addr )", .text = "The field of a sprite's width (FORTH/Sigma game)." },
    .{ .name = "SPRITE-H", .stack = "( spr -- addr )", .text = "The field of a sprite's height (FORTH/Sigma game)." },
    .{ .name = "SPRITE-FRAMES", .stack = "( spr -- addr )", .text = "The field of the number of frames, side by side in the image (FORTH/Sigma game)." },
    .{ .name = "SPRITE-FRAME", .stack = "( spr -- addr )", .text = "The field of the frame shown, from 0 (FORTH/Sigma game)." },
    .{ .name = "SPRITE-DELAY", .stack = "( spr -- addr )", .text = "The field of the calls of ANIMATE each frame is shown for (FORTH/Sigma game)." },
    .{ .name = "SPRITE-TICK", .stack = "( spr -- addr )", .text = "The field of the calls of ANIMATE the frame has been shown for (FORTH/Sigma game)." },
    .{ .name = "SPRITE-FLIP", .stack = "( spr -- addr )", .text = "The field of a sprite's flip: 0 none, 1 left and right, 2 top and bottom, 3 both (FORTH/Sigma game)." },
    .{ .name = "SPRITE-KEY", .stack = "( spr -- addr )", .text = "The field of a sprite's transparent color, -1 for none (FORTH/Sigma game)." },
    .{ .name = "SPRITE-SHOWN", .stack = "( spr -- addr )", .text = "The field of the flag that a sprite is shown (FORTH/Sigma game)." },
    .{ .name = "INIT-SPRITE", .stack = "( img sx sy w h spr -- )", .text = "Make the /SPRITE bytes at spr a sprite of the w by h rectangle at sx sy of img: at 0 0, shown, one frame (FORTH/Sigma game)." },
    .{ .name = "SPRITE:", .stack = "( img sx sy w h \"name\" -- )", .text = "Define a sprite of the w by h rectangle at sx sy of img; name gives its address (FORTH/Sigma game)." },
    .{ .name = "PUT-SPRITE", .stack = "( x y spr -- )", .text = "Put a sprite at x y (FORTH/Sigma game)." },
