    .{ .name = "TCL-ERROR$", .stack = "( -- c-addr u )", .text = "The message of the last Tcl script that failed (FORTH/Sigma graphics)." },
    .{ .name = "TCL-EVENT", .stack = "( -- c-addr u true | false )", .text = "The next text a Tk widget sent with sigma_event, without waiting (FORTH/Sigma graphics)." },
    .{ .name = "TCL-PROGRAM", .stack = "( c-addr u -- )", .text = "Name the Tcl program to start: else SIGMA_WISH, else wish on the PATH (on macOS not /usr/bin/wish), else on Windows Git for Windows's, on macOS Homebrew's or MacPorts's (FORTH/Sigma graphics)." },
    .{ .name = "TCL-STOP", .stack = "( -- )", .text = "End the Tcl program, dropping what it wrote and Sigma did not read; the next TCL starts it again. HOST FUNCTION ERROR (-265) when the host could not see it end (FORTH/Sigma graphics)." },
    .{ .name = "DISPLAY-TK", .stack = "( -- )", .text = "Make SHOW show the image in a Tk window, from which INKEY and MOUSE also read (FORTH/Sigma graphics)." },
    .{ .name = "SCREEN", .stack = "( -- 0 )", .text = "The handle of the screen, the image of GFX-INIT that SHOW shows (FORTH/Sigma graphics)." },
    .{ .name = "NEW-IMAGE", .stack = "( w h -- img )", .text = "Make a black image besides the screen, each side 1 to 16384; at most 256 images and 1 GiB in all, else OUT OF MEMORY. Images are not saved (FORTH/Sigma graphics)." },
    .{ .name = "FREE-IMAGE", .stack = "( img -- )", .text = "Free an image; its handle becomes invalid (-278), and drawing goes back to the screen when it was drawn on (FORTH/Sigma graphics)." },
    .{ .name = "IMAGE-SIZE", .stack = "( img -- w h )", .text = "The width and height of an image, or of the screen (0 0 before GFX-INIT) (FORTH/Sigma graphics)." },
    .{ .name = "DRAW-TO", .stack = "( img -- )", .text = "Make the drawing words, GFX-WIDTH, GFX-HEIGHT, and the SAVE- words use an image; SCREEN for the screen (FORTH/Sigma graphics)." },
    .{ .name = "DRAWING", .stack = "( -- img )", .text = "The handle of the image drawn on (FORTH/Sigma graphics)." },
    .{ .name = "TRANSPARENT", .stack = "( rgb|-1 -- )", .text = "The color COPY-RECT and PUT-IMAGE leave out, or -1 for none (the start) (FORTH/Sigma graphics)." },
    .{ .name = "IMAGE-FLIP", .stack = "( n -- )", .text = "How COPY-RECT and PUT-IMAGE flip: 0 not, 1 left and right, 2 top and bottom, 3 both (FORTH/Sigma graphics)." },
    .{ .name = "COPY-RECT", .stack = "( src sx sy w h dx dy -- )", .text = "Copy the w by h rectangle at sx sy of image src to dx dy of the image drawn on, with TRANSPARENT, IMAGE-FLIP, IMAGE-MODE, and IMAGE-SCALE; parts outside are left out (FORTH/Sigma graphics)." },
    .{ .name = "IMAGE-MODE", .stack = "( n -- )", .text = "How COPY-RECT and PUT-IMAGE put the pixels: 0 over those there (the start), 1 XOR, 2 added (each color at most 255), 3 mixed by IMAGE-ALPHA (FORTH/Sigma graphics)." },
    .{ .name = "IMAGE-ALPHA", .stack = "( n -- )", .text = "How much of the copy IMAGE-MODE 3 shows, 0 (none) to 255 (all); 128 at the start (FORTH/Sigma graphics)." },
    .{ .name = "IMAGE-SCALE", .stack = "( n -- )", .text = "COPY-RECT and PUT-IMAGE draw each pixel n by n, 1 (the start) to 16 (FORTH/Sigma graphics)." },
    .{ .name = "PUT-IMAGE", .stack = "( src x y -- )", .text = "Copy the whole image src to x y of the image drawn on, as COPY-RECT does (FORTH/Sigma graphics)." },
    .{ .name = "LOAD-IMAGE", .stack = "( c-addr u -- img )", .text = "Read a PNG, BMP, or PPM/PGM file into a new image; pixels more than half transparent get the TRANSPARENT color, black when none. IMAGE FORMAT ERROR (-279) for a file it cannot read (FORTH/Sigma graphics)." },
    .{ .name = "GFX-IMAGE-LOAD", .stack = "( c-addr u key -- img ior )", .text = "Primitive for LOAD-IMAGE: key is the color of the transparent pixels, negative for black; ior of opening or reading the file, img 0 then (FORTH/Sigma)." },
    .{ .name = "GFX-IMAGE-NEW", .stack = "( w h -- img )", .text = "Primitive for NEW-IMAGE (FORTH/Sigma)." },
    .{ .name = "GFX-IMAGE-FREE", .stack = "( img -- )", .text = "Primitive for FREE-IMAGE (FORTH/Sigma)." },
    .{ .name = "GFX-IMAGE-SIZE", .stack = "( img -- w h )", .text = "Primitive for IMAGE-SIZE (FORTH/Sigma)." },
    .{ .name = "GFX-TARGET", .stack = "( img -- )", .text = "Primitive for DRAW-TO (FORTH/Sigma)." },
    .{ .name = "GFX-TARGET@", .stack = "( -- img )", .text = "Primitive for DRAWING (FORTH/Sigma)." },
    .{ .name = "GFX-COPY", .stack = "( src sx sy w h dx dy key flip mode alpha scale -- )", .text = "Copy a rectangle to the image drawn on; key is the transparent color or negative, flip 0 to 3, mode 0 to 3, alpha 0 to 255, scale 1 to 16. Flipping or scaling within one image onto an overlapping place is NUMBER ERROR (FORTH/Sigma)." },
    .{ .name = "GFX-COLOR-MODE", .stack = "( n flag -- )", .text = "Show the image with 0 (full color), 2, 16, or 256 colors, dithered when flag is true (FORTH/Sigma)." },
    .{ .name = "DISPLAY-COLORS", .stack = "( n -- )", .text = "Make SHOW use full color (0) or 2, 16, or 256 colors; the image keeps its colors (FORTH/Sigma graphics)." },
    .{ .name = "DITHER", .stack = "( flag -- )", .text = "Make SHOW mix the colors of fewer colors with a 4 by 4 Bayer matrix (true) or take the nearest (FORTH/Sigma graphics)." },
    .{ .name = "GFX-GLYPH-LOAD", .stack = "( code -- advance | -1 )", .text = "Load the glyph of a code point in TEXT's current font; -1 when the font has none (FORTH/Sigma)." },
    .{ .name = "GFX-GLYPH-BOX", .stack = "( -- left width height )", .text = "The box of the loaded glyph, from the pen and the top of the line (FORTH/Sigma)." },
    .{ .name = "GFX-GLYPH-ALPHA", .stack = "( x y -- a )", .text = "The coverage, 0 to 255, of the loaded glyph at x y of its box (FORTH/Sigma)." },
    .{ .name = "GFX-FONT-HEIGHT", .stack = "( -- h )", .text = "The height of a line of TEXT's current font (FORTH/Sigma)." },
    .{ .name = "GFX-FONT-BUILTIN", .stack = "( -- )", .text = "Use the built-in ASCII font for TEXT (FORTH/Sigma)." },
    .{ .name = "GFX-FONT-LOAD", .stack = "( c-addr u -- ior )", .text = "Read a BDF font file for TEXT; ior 0, the file's error, or -272 (FORTH/Sigma)." },
    .{ .name = "GFX-FONT-SYSTEM", .stack = "( c-addr u height -- ior )", .text = "Use the system's font of that name, height pixels a line, for TEXT; ior 0 or -272 (FORTH/Sigma)." },
    .{ .name = "TEXT", .stack = "( c-addr u x y -- )", .text = "Draw the UTF-8 string with the top left of its line at x y, in the current font and color (FORTH/Sigma graphics)." },
    .{ .name = "TEXT-HEIGHT", .stack = "( -- h )", .text = "The height of a line of TEXT, at the current scale (FORTH/Sigma graphics)." },
    .{ .name = "BUILTIN-FONT", .stack = "( -- )", .text = "Draw TEXT with the built-in ASCII font, 4 by 8 pixels (FORTH/Sigma graphics)." },
    .{ .name = "LOAD-FONT", .stack = "( c-addr u -- )", .text = "Read the named BDF font file and draw TEXT with it; THROW on failure (FORTH/Sigma graphics)." },
    .{ .name = "SYSTEM-FONT", .stack = "( c-addr u height -- )", .text = "Draw TEXT with the system's font of that name, height pixels a line, smoothed (Windows; FORTH/Sigma graphics)." },
    .{ .name = "TEXT-SCALE", .stack = "( n -- )", .text = "Draw each pixel of TEXT's font as n by n pixels, 1 to 256; 1 at first (FORTH/Sigma graphics)." },
    .{ .name = "TEXT-WIDTH", .stack = "( c-addr u -- w )", .text = "How many pixels wide TEXT draws the string (FORTH/Sigma graphics)." },
    .{ .name = "INKEY", .stack = "( -- key | -1 )", .text = "The next key pressed, without waiting; -1 when none. Keys that are not characters give K-UP and so on (FORTH/Sigma graphics)." },
    .{ .name = "KEY-HELD?", .stack = "( key -- flag )", .text = "Whether the key (a character of one byte, or K-UP and so on) is held down now; the Windows console and the windows tell when a key is released, while a key from a terminal on Linux or macOS counts as held for 0.6 s after it was pressed (0.12 s once it is repeating), or until another cursor key is pressed if it is a cursor key (FORTH/Sigma graphics)." },
    .{ .name = "WINDOW-SIZE", .stack = "( w h -- )", .text = "Show the image in a window w by h pixels large from the next SHOW, keeping its proportions with black around it; 0 0 for the image's own size (FORTH/Sigma graphics)." },
    .{ .name = "MOUSE", .stack = "( -- x y buttons )", .text = "The pixel of the image under the mouse, -1 -1 when not known, and the buttons held: 1 left, 2 right, 4 middle (FORTH/Sigma graphics)." },
    .{ .name = "MOUSE-ON", .stack = "( -- )", .text = "Have the terminal report the mouse, for MOUSE (FORTH/Sigma graphics)." },
    .{ .name = "MOUSE-OFF", .stack = "( -- )", .text = "Stop the terminal's mouse reports (FORTH/Sigma graphics)." },
    .{ .name = "MOUSE-EVENT", .stack = "( -- x y button kind true | false )", .text = "The oldest mouse event not yet read, without waiting: kind 1 pressed, 2 released (button 1 left, 2 right, 4 middle), 3 the wheel (button 1 up, -1 down); 64 are kept, the oldest dropped (FORTH/Sigma graphics)." },
    .{ .name = "GFX-MOUSE-EVENT", .stack = "( -- x y button kind true | false )", .text = "Primitive for MOUSE-EVENT (FORTH/Sigma)." },
    .{ .name = "FRAME", .stack = "( ms -- )", .text = "Wait until ms milliseconds have passed since the last FRAME, then SHOW, for animation at a steady pace (FORTH/Sigma graphics)." },
    .{ .name = "K-UP", .stack = "( -- key )", .text = "The code INKEY gives for the Up arrow key (FORTH/Sigma graphics)." },
    .{ .name = "K-DOWN", .stack = "( -- key )", .text = "The code INKEY gives for the Down arrow key (FORTH/Sigma graphics)." },
    .{ .name = "K-LEFT", .stack = "( -- key )", .text = "The code INKEY gives for the Left arrow key (FORTH/Sigma graphics)." },
    .{ .name = "K-RIGHT", .stack = "( -- key )", .text = "The code INKEY gives for the Right arrow key (FORTH/Sigma graphics)." },
    .{ .name = "K-HOME", .stack = "( -- key )", .text = "The code INKEY gives for the Home key (FORTH/Sigma graphics)." },
    .{ .name = "K-END", .stack = "( -- key )", .text = "The code INKEY gives for the End key (FORTH/Sigma graphics)." },
    .{ .name = "K-PRIOR", .stack = "( -- key )", .text = "The code INKEY gives for the Page Up key (FORTH/Sigma graphics)." },
    .{ .name = "K-NEXT", .stack = "( -- key )", .text = "The code INKEY gives for the Page Down key (FORTH/Sigma graphics)." },
    .{ .name = "K-INSERT", .stack = "( -- key )", .text = "The code INKEY gives for the Insert key (FORTH/Sigma graphics)." },
    .{ .name = "K-DELETE", .stack = "( -- key )", .text = "The code INKEY gives for the Delete key (FORTH/Sigma graphics)." },
    .{ .name = "K-F1", .stack = "( -- key )", .text = "The code INKEY gives for the F1 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F2", .stack = "( -- key )", .text = "The code INKEY gives for the F2 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F3", .stack = "( -- key )", .text = "The code INKEY gives for the F3 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F4", .stack = "( -- key )", .text = "The code INKEY gives for the F4 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F5", .stack = "( -- key )", .text = "The code INKEY gives for the F5 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F6", .stack = "( -- key )", .text = "The code INKEY gives for the F6 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F7", .stack = "( -- key )", .text = "The code INKEY gives for the F7 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F8", .stack = "( -- key )", .text = "The code INKEY gives for the F8 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F9", .stack = "( -- key )", .text = "The code INKEY gives for the F9 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F10", .stack = "( -- key )", .text = "The code INKEY gives for the F10 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F11", .stack = "( -- key )", .text = "The code INKEY gives for the F11 key (FORTH/Sigma graphics)." },
    .{ .name = "K-F12", .stack = "( -- key )", .text = "The code INKEY gives for the F12 key (FORTH/Sigma graphics)." },
    // The floating-point part of the graphics library (src/graphics/graphics_float.fs).
    .{ .name = "X-RANGE", .stack = "( F: lo hi -- )", .text = "Make the image show x from lo at the left edge to hi at the right one; -1 to 1 at first (FORTH/Sigma graphics)." },
    .{ .name = "Y-RANGE", .stack = "( F: lo hi -- )", .text = "Make the image show y from lo at the bottom edge to hi at the top one; -1 to 1 at first (FORTH/Sigma graphics)." },
    .{ .name = "MPSET", .stack = "( F: x y -- )", .text = "Set the pixel at the mathematical coordinates x y to the current color (FORTH/Sigma graphics)." },
    .{ .name = "MLINE", .stack = "( F: x1 y1 x2 y2 -- )", .text = "Draw a line between two points in mathematical coordinates (FORTH/Sigma graphics)." },
    .{ .name = "AXES", .stack = "( -- )", .text = "Draw the axes x = 0 and y = 0 that are in the range, with the current color (FORTH/Sigma graphics)." },
    .{ .name = "PLOT", .stack = "( xt -- )", .text = "Draw the graph of xt ( F: x -- y ) across the image, joining the columns with lines; NaN leaves a gap (FORTH/Sigma graphics)." },
    // Audio (FORTH/Sigma): the SND- words and the audio library are in the AUDIO vocabulary.
    .{ .name = "REQUIRE-AUDIO", .stack = "( -- )", .text = "Load the audio words into the AUDIO vocabulary, the first time only (FORTH/Sigma)." },
    .{ .name = "SND-PLAY", .stack = "( c-addr1 u1 c-addr2 u2 c-addr3 u3 -- )", .text = "Put the MML of the three voices of one PLAY; an empty string for a voice that has no notes (FORTH/Sigma)." },
    .{ .name = "SND-SOUND", .stack = "( reg value -- )", .text = "Host primitive for SOUND (FORTH/Sigma)." },
    .{ .name = "SND-BEEP", .stack = "( -- )", .text = "Host primitive for BEEP (FORTH/Sigma)." },
    .{ .name = "SND-PLAYING", .stack = "( n -- flag )", .text = "Host primitive for PLAY? (FORTH/Sigma)." },
    .{ .name = "SND-DEVICE", .stack = "( -- flag )", .text = "Host primitive for AUDIO? (FORTH/Sigma)." },
    .{ .name = "PLAY", .stack = "( c-addr u -- )", .text = "Play MSX BASIC's MML on voice A, returning once the notes fit in the queue; an invalid string throws -274 (FORTH/Sigma audio)." },
    .{ .name = "PLAY2", .stack = "( c-addr1 u1 c-addr2 u2 -- )", .text = "Play MML on voices A and B, starting together (FORTH/Sigma audio)." },
    .{ .name = "PLAY3", .stack = "( c-addr1 u1 c-addr2 u2 c-addr3 u3 -- )", .text = "Play MML on voices A, B, and C, starting together (FORTH/Sigma audio)." },
    .{ .name = "PLAY?", .stack = "( n -- flag )", .text = "Whether voice n (1 to 8), or any voice for 0, still has notes to play, as MSX BASIC's PLAY(n) (FORTH/Sigma audio)." },
    .{ .name = "SOUND", .stack = "( reg value -- )", .text = "Write a value 0 to 255 to the PSG's register 0 to 13, as MSX BASIC's SOUND (FORTH/Sigma audio)." },
    .{ .name = "BEEP", .stack = "( -- )", .text = "Stop the music, set the PSG and the PLAY settings as at start, and beep (FORTH/Sigma audio)." },
    .{ .name = "AUDIO?", .stack = "( -- flag )", .text = "Whether the sound reaches an audio device; without one the words work silently (FORTH/Sigma audio)." },
    .{ .name = "SND-PLAYS", .stack = "( c-addr1 u1 ... c-addrn un n -- )", .text = "Host primitive for PLAYS (FORTH/Sigma)." },
    .{ .name = "SND-CHIP", .stack = "( n -- )", .text = "Host primitive for MSX-SOUND (0), ST-SOUND (1), NES-SOUND (2), C64-SOUND (3), SCC-SOUND (4), and AMIGA-SOUND (5) (FORTH/Sigma)." },
    .{ .name = "SND-INSTRUMENT", .stack = "( n -- )", .text = "Host primitive for INSTRUMENT (FORTH/Sigma)." },
    .{ .name = "SND-WAVE", .stack = "( n -- )", .text = "Host primitive for SQUARE (0), PULSE (1), TRIANGLE (2), SAW (3), and NOISE (4) (FORTH/Sigma)." },
    .{ .name = "SND-DUTY", .stack = "( percent -- )", .text = "Host primitive for DUTY (FORTH/Sigma)." },
    .{ .name = "SND-ADSR", .stack = "( a d s r -- )", .text = "Host primitive for ADSR (FORTH/Sigma)." },
    .{ .name = "PLAYS", .stack = "( c-addr1 u1 ... c-addrn un n -- )", .text = "Play MML on the first n voices, starting together; n is 1 to 8 (FORTH/Sigma audio)." },
    .{ .name = "MSX-SOUND", .stack = "( -- )", .text = "Play PLAY on the MSX's AY-3-8910 (3 voices), as at start; the music stops (FORTH/Sigma audio)." },
    .{ .name = "ST-SOUND", .stack = "( -- )", .text = "Play PLAY on the Atari ST's YM2149 at 2 MHz (3 voices); the music stops (FORTH/Sigma audio)." },
    .{ .name = "NES-SOUND", .stack = "( -- )", .text = "Play PLAY on the NES's APU: pulse, pulse, triangle, noise; the music stops (FORTH/Sigma audio)." },
    .{ .name = "INSTRUMENT", .stack = "( n -- )", .text = "Choose instrument n (0 to 63), which MML's @n plays with, for the words that change it (FORTH/Sigma audio)." },
    .{ .name = "SQUARE", .stack = "( -- )", .text = "Make the instrument a square wave, a pulse of 50% (FORTH/Sigma audio)." },
    .{ .name = "PULSE", .stack = "( -- )", .text = "Make the instrument a pulse of DUTY's width; the NES takes 12.5, 25, 50, or 75% (FORTH/Sigma audio)." },
    .{ .name = "TRIANGLE", .stack = "( -- )", .text = "Make the instrument a triangle wave, on the chips that let it choose (FORTH/Sigma audio)." },
    .{ .name = "SAW", .stack = "( -- )", .text = "Make the instrument a sawtooth wave, on the chips that let it choose (FORTH/Sigma audio)." },
    .{ .name = "NOISE", .stack = "( -- )", .text = "Make the instrument noise, on the chips that let it choose (FORTH/Sigma audio)." },
    .{ .name = "DUTY", .stack = "( percent -- )", .text = "Set the width of the instrument's pulse, 0 to 100 percent; 50 at first (FORTH/Sigma audio)." },
    .{ .name = "ADSR", .stack = "( a d s r -- )", .text = "Set the instrument's envelope, each 0 to 15 as on the C64's SID; 0 0 15 0 at first (FORTH/Sigma audio)." },
    .{ .name = "SND-RING", .stack = "( flag -- )", .text = "Host primitive for RING (FORTH/Sigma)." },
    .{ .name = "SND-SYNC", .stack = "( flag -- )", .text = "Host primitive for SYNC (FORTH/Sigma)." },
    .{ .name = "SND-FILTER", .stack = "( mode cutoff resonance -- )", .text = "Host primitive for FILTER (FORTH/Sigma)." },
    .{ .name = "C64-SOUND", .stack = "( -- )", .text = "Play PLAY on the C64's SID (PAL, 3 voices); the music stops (FORTH/Sigma audio)." },
    .{ .name = "RING", .stack = "( flag -- )", .text = "Ring-modulate the instrument's triangle by the voice before (voice 1 by voice 3) on the C64 (FORTH/Sigma audio)." },
    .{ .name = "SYNC", .stack = "( flag -- )", .text = "Restart the instrument's wave with each cycle of the voice before (voice 1 by voice 3) on the C64 (FORTH/Sigma audio)." },
    .{ .name = "FILTER", .stack = "( mode cutoff resonance -- )", .text = "Send the instrument through the C64's filter: mode 0 none, 1 low-pass, 2 band-pass, 3 high-pass; cutoff 0 to 2047, resonance 0 to 15. The voices share one filter, set by the last note that uses it (FORTH/Sigma audio)." },
    .{ .name = "SND-WAVETABLE", .stack = "( c-addr n -- )", .text = "Host primitive for SCC-WAVE (FORTH/Sigma)." },
    .{ .name = "SCC-SOUND", .stack = "( -- )", .text = "Play PLAY on Konami's SCC (5 voices of 32-sample waves); the music stops (FORTH/Sigma audio)." },
    .{ .name = "SND-LOAD-SAMPLE", .stack = "( c-addr u n -- ior )", .text = "Host primitive for LOAD-SAMPLE: ior 0, the file's, -276, or -257 (FORTH/Sigma)." },
    .{ .name = "SND-SAMPLE", .stack = "( c-addr u rate n -- )", .text = "Host primitive for SAMPLE (FORTH/Sigma)." },
    .{ .name = "SND-LOOP-SAMPLE", .stack = "( start end n -- )", .text = "Host primitive for LOOP-SAMPLE (FORTH/Sigma)." },
    .{ .name = "SND-SAMPLE-INSTRUMENT", .stack = "( n -- )", .text = "Host primitive for SAMPLE-INSTRUMENT (FORTH/Sigma)." },
    .{ .name = "SND-SFX", .stack = "( n -- )", .text = "Host primitive for SFX (FORTH/Sigma)." },
    .{ .name = "SND-AMIGA-FILTER", .stack = "( flag -- )", .text = "Host primitive for AMIGA-FILTER (FORTH/Sigma)." },
    .{ .name = "SND-FREE-SAMPLES", .stack = "( -- )", .text = "Host primitive for FREE-SAMPLES (FORTH/Sigma)." },
    .{ .name = "LOAD-SAMPLE", .stack = "( c-addr u n -- )", .text = "Read a WAV file of 8- or 16-bit PCM into sample n (0 to 63), as mono; SAMPLE ERROR (-276) for other files, OUT OF MEMORY when the 64 MiB pool is full (FORTH/Sigma audio)." },
    .{ .name = "SAMPLE", .stack = "( c-addr u rate n -- )", .text = "Make the u signed 8-bit bytes at c-addr sample n, recorded at rate Hz (1000 to 192000) (FORTH/Sigma audio)." },
    .{ .name = "LOOP-SAMPLE", .stack = "( start end n -- )", .text = "Loop sample n from frame start to frame end; 0 0 for no loop (FORTH/Sigma audio)." },
    .{ .name = "SAMPLE-INSTRUMENT", .stack = "( n -- )", .text = "Have the instrument play sample n on the Amiga, O4's C at the sample's rate; -1 for none (FORTH/Sigma audio)." },
    .{ .name = "SFX", .stack = "( n -- )", .text = "Play sample n once at its rate, at once and beside the music, on any chip; four can sound together (FORTH/Sigma audio)." },
    .{ .name = "FREE-SAMPLES", .stack = "( -- )", .text = "Stop the music and the SFX and forget every sample, emptying the pool (FORTH/Sigma audio)." },
    .{ .name = "AMIGA-SOUND", .stack = "( -- )", .text = "Play PLAY on the Amiga's Paula (PAL, 4 voices of samples, left right right left); the music stops (FORTH/Sigma audio)." },
    .{ .name = "AMIGA-FILTER", .stack = "( flag -- )", .text = "Turn the Amiga's LED filter (a low-pass at about 3.3 kHz) on or off; off at first (FORTH/Sigma audio)." },
    .{ .name = "SND-LOAD-MOD", .stack = "( c-addr u -- ior )", .text = "Host primitive for LOAD-MOD: ior 0, the file's, -277, or -257 (FORTH/Sigma)." },
    .{ .name = "SND-PLAY-MOD", .stack = "( flag -- )", .text = "Host primitive for PLAY-MOD (FORTH/Sigma)." },
    .{ .name = "SND-STOP-MOD", .stack = "( -- )", .text = "Host primitive for STOP-MOD (FORTH/Sigma)." },
    .{ .name = "SND-MOD-PLAYING", .stack = "( -- flag )", .text = "Host primitive for MOD? (FORTH/Sigma)." },
    .{ .name = "LOAD-MOD", .stack = "( c-addr u -- )", .text = "Read a ProTracker module (MOD, 4 channels, 31 samples) into the pool; MOD ERROR (-277) for other files, OUT OF MEMORY when the pool is full (FORTH/Sigma audio)." },
    .{ .name = "PLAY-MOD", .stack = "( flag -- )", .text = "Play the module from its start, beside PLAY and SFX; again after its end when flag is true; with a false flag, a song that jumps back to a row it has played ends there (FORTH/Sigma audio)." },
    .{ .name = "STOP-MOD", .stack = "( -- )", .text = "Stop the module (FORTH/Sigma audio)." },
    .{ .name = "MOD?", .stack = "( -- flag )", .text = "Whether the module plays (FORTH/Sigma audio)." },
    .{ .name = "SND-CHIPS", .stack = "( mask -- )", .text = "Host primitive for CHIPS (FORTH/Sigma)." },
    .{ .name = "CHIPS", .stack = "( mask -- )", .text = "Give the voices several chips, e.g. MSX SCC OR CHIPS; they are numbered in the order MSX ST NES C64 SCC AMIGA, and the voices after those sound like the last chip; the music stops (FORTH/Sigma audio)." },
    .{ .name = "SND-STYLE", .stack = "( chip -- )", .text = "Host primitive for STYLE (FORTH/Sigma)." },
    .{ .name = "STYLE", .stack = "( chip -- )", .text = "Make the instrument sound like a chip on any voice: MSX, ST, NES, C64, SCC, or AMIGA; 0 for the chip of the voice that plays it (FORTH/Sigma audio)." },
    .{ .name = "MSX", .stack = "( -- 1 )", .text = "The MSX's PSG for CHIPS (3 voices) (FORTH/Sigma audio)." },
    .{ .name = "ST", .stack = "( -- 2 )", .text = "The Atari ST's YM2149 for CHIPS (3 voices) (FORTH/Sigma audio)." },
